    ink.strokeStyle='#71593730';ink.lineWidth=2+i%3;ink.beginPath();ink.moveTo(q.x+q.nx*offset,q.y+q.ny*offset);ink.lineTo(p.x+p.nx*offset,p.y+p.ny*offset);ink.stroke();
