"src/rendering/art/animation-art.js": function(require, exports){
const {CharacterFrames} = require("src/rendering/character-frames.js");
const ids=Object.keys(CharacterFrames.manifest.characters).filter(id=>CharacterFrames.manifest.characters[id].renderer==='animation');
const AnimationArt={
 status:CharacterFrames.register(ids,'animation-art-ready'),
 get(name,variant=0,action='walk',progress=0){
  const id=name==='roman'?'roman-'+((Math.floor(variant)%3+3)%3):name;
  return ids.includes(id)?CharacterFrames.get(id,action,progress):null;
 },
};

Object.defineProperty(exports, "AnimationArt", {get: () => AnimationArt});
},
"src/world/village/village.js": function(require, exports){
const {VillageData} = require("src/world/village/village-data.js");
const {VillageCollision} = require("src/world/village/collision.js");
const {VillageNavigation} = require("src/world/village/navigation.js");
const {VillageRenderer} = require("src/world/village/village-renderer.js");
const {VillageArt} = require("src/rendering/art/village-art.js");
let Village;
'use strict';
Village=(()=>{
const data=VillageData.create();
const collision=VillageCollision.create(data.objects,data.size);
const navigation=VillageNavigation.create({...data,...collision});
const renderer=VillageRenderer.create({...data,document:typeof document==='undefined'?null:document,VillageArt:typeof VillageArt==='undefined'?null:VillageArt});
return {...data,...navigation,...renderer,collision,blocked:collision.blocked,clear:collision.clear};
})();

Object.defineProperty(exports, "Village", {get: () => Village});
},
